<script setup lang="ts">
import { ChevronLeft, ChevronRight, Search, Close } from './internal/icons';
import RenderNode from './internal/RenderNode';
import { ref, computed } from 'vue'; import type { CSSProperties } from 'vue';
import './styles/theme.css'; import './styles/transfer.css';
interface Item { key: string; title: string; description?: import('vue').VNodeChild; disabled?: boolean }
type Direction = 'left' | 'right';
const props = withDefaults(defineProps<{ dataSource: Item[]; targetKeys?: string[]; defaultTargetKeys?: string[]; selectedKeys?: string[]; titles?: [import('vue').VNodeChild, import('vue').VNodeChild]; operations?: [string, string]; showSearch?: boolean; searchPlaceholder?: string; filterOption?: (query: string, item: Item) => boolean; showSelectAll?: boolean; oneWay?: boolean; disabled?: boolean; listStyle?: CSSProperties; notFoundContent?: string }>(), { defaultTargetKeys: () => [], titles: () => ['可选项目', '已选项目'], operations: () => ['移至已选', '移回可选'], searchPlaceholder: '搜索…', showSelectAll: true, notFoundContent: '暂无数据' });
const emit = defineEmits<{ 'update:targetKeys': [keys: string[]]; change: [keys: string[], direction: Direction, moveKeys: string[]]; 'update:selectedKeys': [keys: string[]]; selectChange: [sourceKeys: string[], targetKeys: string[]] }>(); const inner = ref(props.defaultTargetKeys), innerSelected = ref<string[]>([]), queries = ref({ left: '', right: '' }); const targets = computed(() => props.targetKeys ?? inner.value); const selected = computed(() => props.selectedKeys ?? innerSelected.value);
const lists = computed(() => ({ left: props.dataSource.filter(item => !targets.value.includes(item.key)), right: targets.value.map(key => props.dataSource.find(item => item.key === key)).filter((item): item is Item => !!item) }));
function visible(direction: Direction) { const query = queries.value[direction].trim(); return lists.value[direction].filter(item => !query || (props.filterOption ? props.filterOption(query, item) : item.title.toLocaleLowerCase().includes(query.toLocaleLowerCase()))); }
function selectedHere(direction: Direction) { return lists.value[direction].filter(item => !item.disabled && selected.value.includes(item.key)).map(item => item.key); }
function updateSelected(next: string[]) { if (props.selectedKeys === undefined) innerSelected.value = next; emit('update:selectedKeys', next); emit('selectChange', next.filter(key => !targets.value.includes(key)), next.filter(key => targets.value.includes(key))); }
function choose(key: string, event: Event) { const checked = (event.target as HTMLInputElement).checked; updateSelected(checked ? [...new Set([...selected.value, key])] : selected.value.filter(item => item !== key)); }
function all(direction: Direction, event: Event) { const keys = visible(direction).filter(item => !item.disabled).map(item => item.key); updateSelected((event.target as HTMLInputElement).checked ? [...new Set([...selected.value, ...keys])] : selected.value.filter(key => !keys.includes(key))); }
function allChecked(direction: Direction) { const items = visible(direction).filter(item => !item.disabled); return items.length > 0 && items.every(item => selected.value.includes(item.key)); }
function move(direction: Direction, raw: string[]) { if (props.disabled) return; const keys = raw.filter(key => !props.dataSource.find(item => item.key === key)?.disabled); if (!keys.length) return; const next = direction === 'right' ? [...new Set([...targets.value, ...keys])] : targets.value.filter(key => !keys.includes(key)); if (props.targetKeys === undefined) inner.value = next; emit('update:targetKeys', next); emit('change', next, direction, keys); updateSelected(selected.value.filter(key => !keys.includes(key))); }
</script>
<template><div :class="['at-transfer', { 'at-transfer--one-way': oneWay }]"><template v-for="(direction, index) in (['left', 'right'] as const)" :key="direction"><section :class="['at-transfer__panel', { 'at-transfer__panel--disabled': disabled }]" :style="listStyle" :aria-label="typeof titles[index] === 'string' ? titles[index] : direction === 'left' ? '可选项目' : '已选项目'"><header class="at-transfer__header"><input v-if="showSelectAll && !(oneWay && direction === 'right')" type="checkbox" class="at-transfer__checkbox" :aria-label="`全选${titles[index]}`" :checked="allChecked(direction)" :indeterminate="selectedHere(direction).length > 0 && !allChecked(direction)" :disabled="disabled || !visible(direction).some(item => !item.disabled)" @change="all(direction, $event)"><strong><RenderNode :content="titles[index]" /></strong><span class="at-transfer__count">{{ selectedHere(direction).length ? `${selectedHere(direction).length}/${lists[direction].length}` : lists[direction].length }} 项</span></header><label v-if="showSearch" class="at-transfer__search"><span aria-hidden="true"><Search :size="14" /></span><input v-model="queries[direction]" :placeholder="searchPlaceholder" :aria-label="`搜索${titles[index]}`" :disabled="disabled"><button v-if="queries[direction]" type="button" aria-label="清空搜索" @click="queries[direction] = ''"><Close :size="14" /></button></label><ul class="at-transfer__list" role="list"><li v-if="!visible(direction).length" class="at-transfer__empty">{{ notFoundContent }}</li><li v-for="item in visible(direction)" :key="item.key" :class="['at-transfer__item', { 'at-transfer__item--checked': selected.includes(item.key), 'at-transfer__item--disabled': item.disabled }]"><label class="at-transfer__option"><input v-if="!(oneWay && direction === 'right')" type="checkbox" class="at-transfer__checkbox" :checked="selected.includes(item.key)" :disabled="disabled || item.disabled" @change="choose(item.key, $event)"><span class="at-transfer__text"><slot name="item" :item="item">{{ item.title }}</slot><small v-if="item.description"><RenderNode :content="item.description" /></small></span></label><button v-if="oneWay && direction === 'right'" type="button" class="at-transfer__remove" :aria-label="`移除 ${item.title}`" :disabled="disabled || item.disabled" @click="move('left', [item.key])"><Close :size="14" /></button></li></ul><footer v-if="$slots.footer" class="at-transfer__footer"><slot name="footer" :direction="direction" :total="lists[direction].length" :selected="selectedHere(direction).length" /></footer></section><div v-if="direction === 'left'" class="at-transfer__actions"><button type="button" class="at-transfer__move" :disabled="disabled || !selectedHere('left').length" :aria-label="operations[0]" @click="move('right', selectedHere('left'))"><ChevronRight :size="16" /><span v-if="selectedHere('left').length" class="at-transfer__move-count">{{ selectedHere('left').length }}</span></button><button v-if="!oneWay" type="button" class="at-transfer__move" :disabled="disabled || !selectedHere('right').length" :aria-label="operations[1]" @click="move('left', selectedHere('right'))"><ChevronLeft :size="16" /><span v-if="selectedHere('right').length" class="at-transfer__move-count">{{ selectedHere('right').length }}</span></button></div></template></div></template>
